morse.watch("body", body => {
  const bar = morse.el("div", { id: "morse-progress" });
  body.appendChild(bar);
  const update = () => {
    const art = document.querySelector("div.wrap > article");
    let pct;
    if (art) {
      const r = art.getBoundingClientRect();
      const total = r.height - window.innerHeight;
      pct = total > 0 ? -r.top / total : (r.bottom <= window.innerHeight ? 1 : 0);
    } else {
      const max = document.documentElement.scrollHeight - window.innerHeight;
      pct = max > 0 ? window.scrollY / max : 1;
    }
    bar.style.width = Math.max(0, Math.min(1, pct)) * 100 + "%";
  };
  morse.on(window, "scroll", update);
  morse.on(window, "resize", update);
  update();
});

