morse.watch('div[aria-label="Tools"]', tools => {
  const pen = tools.querySelector('button[aria-label="Pen"]');
  const btn = morse.el('button', {
    class: ((pen && pen.className) ? pen.className + ' ' : '') + 'morse-save-png',
    'aria-label': 'Save as PNG',
    title: 'Save as PNG',
    text: '💾',
    on: { click: () => {
      const board = document.querySelector('#board');
      if (!board) return morse.toast('No drawing found');
      const out = document.createElement('canvas');
      out.width = board.width; out.height = board.height;
      const ctx = out.getContext('2d');
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, out.width, out.height);
      const layers = morse.$$('.stage canvas').filter(c => c.width === board.width && c.height === board.height);
      (layers.length ? layers : [board]).forEach(c => ctx.drawImage(c, 0, 0));
      out.toBlob(blob => {
        if (!blob) return morse.toast('Could not save the drawing');
        const url = URL.createObjectURL(blob);
        const title = (document.title.split('·')[0] || 'sketch').trim() || 'sketch';
        const a = morse.el('a', { href: url, download: title + '.png' });
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        morse.toast('Saved ' + title + '.png');
      }, 'image/png');
    } }
  });
  tools.appendChild(btn);
});

