const KEY = "orders-amount-sort";
const num = el => parseFloat((el?.textContent || "").replace(/[^0-9.\-]/g, "")) || 0;

function apply(tbody) {
  const dir = morse.store.get(KEY);
  if (!dir) return;
  const rows = [...tbody.querySelectorAll(":scope > tr")];
  const sorted = rows.slice().sort((a, b) => {
    const d = num(a.querySelector("td.am")) - num(b.querySelector("td.am"));
    return dir === "asc" ? d : -d;
  });
  if (sorted.some((r, i) => r !== rows[i])) sorted.forEach(r => tbody.appendChild(r));
}

morse.watch("div.tbl table thead th.am", th => {
  const dir = morse.store.get(KEY);
  if (dir) th.setAttribute("data-sort", dir); else th.removeAttribute("data-sort");
  th.title = "Sort by amount";
  morse.on(th, "click", () => {
    const next = morse.store.get(KEY) === "desc" ? "asc" : "desc";
    morse.store.set(KEY, next);
    morse.$$("div.tbl table thead th.am").forEach(h => h.setAttribute("data-sort", next));
    morse.$$("div.tbl table tbody").forEach(apply);
  });
});

morse.watch("div.tbl table tbody", apply, { live: true });

