morse.watch('div[aria-label="Formatting"]', bar => {
  const btn = morse.el('button', {
    class: 'morse-date',
    title: "Insert today's date",
    text: '📅',
    on: {
      mousedown: e => e.preventDefault(),
      click: () => {
        const ed = document.querySelector('div.doc div[role="textbox"]');
        if (!ed) return;
        const date = new Date().toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
        const sel = window.getSelection();
        let inEd = sel.rangeCount && ed.contains(sel.getRangeAt(0).commonAncestorContainer);
        if (!inEd) {
          ed.focus();
          const r = document.createRange();
          r.selectNodeContents(ed.lastElementChild || ed);
          r.collapse(false);
          sel.removeAllRanges();
          sel.addRange(r);
        }
        if (!document.execCommand('insertText', false, date)) {
          const r = sel.getRangeAt(0);
          r.deleteContents();
          const t = document.createTextNode(date);
          r.insertNode(t);
          r.setStartAfter(t); r.collapse(true);
          sel.removeAllRanges(); sel.addRange(r);
        }
      }
    }
  });
  bar.appendChild(btn);
});

const count = () => {
