var FENCE = String.fromCharCode(96).repeat(3);
morse.watch('body > main > header[role="banner"] > div.h7r', function (bar) {
  var btn = morse.el('button', {
    class: 'morse-copy-md',
    text: 'Copy as Markdown',
    title: 'Copy conversation as Markdown',
    on: { click: function () {
      var msgs = morse.$$('section[aria-label="Conversation"] .msg[data-role]');
      if (!msgs.length) { morse.toast('No messages to copy'); return; }
      var md = msgs.map(function (m) {
        var role = m.getAttribute('data-role') || 'message';
        var who = role === 'user' ? 'You' : role === 'assistant' ? 'Parley' : role.charAt(0).toUpperCase() + role.slice(1);
        var blocks = Array.prototype.slice.call(m.querySelectorAll('p, pre, li, h1, h2, h3, h4, blockquote'));
        var body;
        if (blocks.length) {
          body = blocks.filter(function (b) {
            return b.tagName === 'LI' || !b.parentElement.closest('pre, li, blockquote');
          }).map(function (b) {
            var t = b.innerText.trim();
            if (b.tagName === 'PRE') return FENCE + '\n' + t + '\n' + FENCE;
            if (b.tagName === 'LI') return (b.parentElement.tagName === 'OL' ? '1. ' : '- ') + t;
            if (/^H\d$/.test(b.tagName)) return '#'.repeat(+b.tagName.charAt(1) + 1) + ' ' + t;
            if (b.tagName === 'BLOCKQUOTE') return t.split('\n').map(function (l) { return '> ' + l; }).join('\n');
            return t;
          }).join('\n\n');
        } else {
          body = m.innerText.trim();
        }
        return '**' + who + ':**\n\n' + body;
      }).join('\n\n---\n\n');
      var done = function () { morse.toast('Copied ' + msgs.length + ' messages as Markdown'); };
      var fallback = function () {
        var ta = morse.el('textarea', { style: 'position:fixed;opacity:0' });
        ta.value = md;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        ta.remove();
        done();
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(md).then(done, fallback);
      } else {
        fallback();
      }
    } }
  });
  bar.prepend(btn);
});

