const CARDS = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div";
let on = morse.store.get("sortByPrice") === true;

const priceOf = card => {
  const p = card.querySelector(":scope > div:nth-of-type(2) > div:nth-of-type(3)");
  const n = parseFloat((p ? p.textContent : "").replace(/[^0-9.]/g, ""));
  return isNaN(n) ? 999999 : n;
};
const apply = card => { card.style.order = on ? String(Math.round(priceOf(card) * 100)) : ""; };

morse.watch(CARDS, apply, { live: true });

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  const btn = morse.el("button", {
    class: "morse-sort-btn",
    type: "button",
    "aria-pressed": String(on),
    text: "Price: low to high",
    on: { click: () => {
      on = !on;
      morse.store.set("sortByPrice", on);
      btn.setAttribute("aria-pressed", String(on));
      morse.$$(CARDS).forEach(apply);
    } }
  });
  bar.appendChild(btn);
});

