const steps = [0, 15, 30, 60];
let end = morse.store.get("sleepEnd") || 0;
const btns = [];

function label() {
  const left = end - Date.now();
  btns.forEach(b => {
    b.classList.toggle("on", left > 0);
    b.textContent = left > 0 ? "☾ " + Math.ceil(left / 60000) + "m" : "☾ Sleep";
    b.title = left > 0 ? "Sleep timer on, click to change" : "Set a sleep timer";
  });
}

function cycle() {
  const left = end > Date.now() ? Math.ceil((end - Date.now()) / 60000) : 0;
  const next = steps.find(m => m > left) || 0;
  end = next ? Date.now() + next * 60000 : 0;
  morse.store.set("sleepEnd", end);
  morse.toast(next ? "Music will stop in " + next + " min" : "Sleep timer off");
  label();
}

morse.watch('[data-testid="player-controls"] .btns', el => {
  const b = morse.el("button", { class: "morse-sleep", "aria-label": "Sleep timer", on: { click: cycle } });
  el.appendChild(b);
  btns.push(b);
  label();
});

morse.every(1000, () => {
  if (end && Date.now() >= end) {
    end = 0;
    morse.store.set("sleepEnd", 0);
    const pp = document.querySelector('[data-testid="play-pause"]');
    if (pp && pp.getAttribute("aria-label") === "Pause") pp.click();
    morse.toast("Sleep timer: music paused");
  }
  label();
});

morse.on(document, "keydown", e => {
  if (e.code !== "Space" && e.key !== " ") return;
  if (e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
  const t = e.target;
  if (t && (t.closest("input, textarea, select, button, [contenteditable], [contenteditable='true']"))) return;
  const btn = morse.$$('button[data-testid="play-pause"]')[0];
  if (!btn) return;
  e.preventDefault();
  btn.click();
});

