const ROW = 'div[aria-label="Log\\ lines"] > div.sz > div.row';
morse.watch(ROW, row => {
  if (row.querySelector(':scope > .copy-btn')) return;
  const btn = morse.el('button', {
    class: 'copy-btn',
    type: 'button',
    title: 'Copy line',
    text: 'Copy',
    on: {
      click: e => {
        e.stopPropagation();
        const f = s => (row.querySelector(s)?.textContent || '').trim();
        const line = [f('.ts'), f('.lv'), f('.svc'), f('.msg')].join(' ');
        const done = () => {
          btn.textContent = 'Copied';
          setTimeout(() => (btn.textContent = 'Copy'), 1200);
        };
        if (navigator.clipboard && window.isSecureContext) {
          navigator.clipboard.writeText(line).then(done, () => fallback(line, done));
        } else fallback(line, done);
      }
    }
  });
  row.appendChild(btn);
});
function fallback(text, done) {
  const ta = morse.el('textarea', { style: 'position:fixed;opacity:0;top:0;left:0' });
  ta.value = text;
  document.body.appendChild(ta);
  ta.select();
  try { document.execCommand('copy'); done(); } catch (_) { morse.toast('Copy failed'); }
  ta.remove();
}

