morse.watch("#where", h => {
  if (h.nextElementSibling && h.nextElementSibling.classList.contains("morse-all-off")) return;
  const btn = morse.el("button", {
    class: "morse-all-off",
    type: "button",
    text: "⏻ Turn all off",
    on: {
      click: () => {
        const ons = morse.$$("device-card >>> button[aria-label$=': on']").filter(b => !b.disabled);
        ons.forEach(b => b.click());
        const skipped = morse.$$("device-card >>> button[aria-label$=': on']").filter(b => b.disabled).length;
        morse.toast(ons.length
          ? `Turned off ${ons.length} device${ons.length > 1 ? "s" : ""}` + (skipped ? ` (${skipped} locked)` : "")
          : "Everything is already off");
      }
    }
  });
  h.after(btn);
});

